sub(r"function load\(\)\{.*?\}\nfunction showGame",r"""function load(){try{const s=JSON.parse(localStorage.getItem(SAVE));if(!s)return false;player=s.player;ensureInventory();ensureMetaSystems();world=s.world||'city';mission=s.mission||S.GO_GUILD;if(world==='camp'){spawnGoblins();(s.goblins||[]).forEach((v,i)=>Object.assign(goblins[i],v))}else if(world==='cistern'){spawnCisternBoss()}else if(world==='road'){spawnRoadEncounter()}else if(world==='quarry'){spawnQuarryEncounter()}else if(world==='garden'){spawnGardenEncounter()}else if(world==='rift'){spawnDynamicRift()}showGame();return true}catch{return false}}
function showGame""",'load meta')
