sub(r"function objectiveText\(\)\{.*?\}\nfunction updateHud",r'''function objectiveText(){ensureMetaSystems();if(world==='base')return'Sua Base: colete recursos, produção e melhore construções.';if(player.missionAI&&player.missionAI.active){const a=player.missionAI.active;if(world==='rift')return a.ready?'Missão dinâmica concluída. Retorne pelo portal.':`${a.title} (${a.kills||0}/${a.target})`;if(world==='city')return`Missão dinâmica: ${a.title}. Vá ao Portal.`}if(world==='camp'&&mission===S.GOBLINS){const n=goblins.filter(g=>g.dead).length;return n>=5?'Missão concluída. Volte pelo portal.':`Elimine Goblins (${n}/5)`}return({[S.GO_GUILD]:'Entre na Guilda dos Aventureiros.',[S.REGISTER]:'Fale com a Atendente e faça seu registro.',[S.CAPTAIN]:'Fale com o Capitão ao lado do Quadro.',[S.BOARD]:'Consulte o Quadro de Missões e aceite a missão dos Goblins.',[S.PORTAL]:'Saia da Guilda e vá até o Portal Rank F.',[S.RETURN_GUILD]:'Retorne à Guilda para entregar a prova da missão.',[S.REPORT]:'Fale com a Atendente para registrar a conclusão.',[S.CAPTAIN_AFTER]:'Fale com Raul Vilar. Ele tem uma nova missão para você.',[S.DONE]:campaignObjective()})[mission]||''}
function updateHud''','dynamic objective')
s=s.replace("document.getElementById('cardChip').textContent=player.guildCard?'Carteirinha Rank F':'Sem registro';objective.innerHTML='<b>Objetivo:</b> '+objectiveText()","document.getElementById('cardChip').textContent=player.guildCard?'Carteirinha Rank F':'Sem registro';ensureMetaSystems();document.getElementById('materialsChip').textContent=resourceText();objective.innerHTML='<b>Objetivo:</b> '+objectiveText()",1)

