sub(r"function target\(\)\{.*?\}\nfunction arrowToTarget",r'''function target(){if(world==='rift'){const a=player.missionAI&&player.missionAI.active;if(a&&a.ready)return rift.returnPortal;return goblins.find(g=>!g.dead)||rift.returnPortal}if(world==='base')return baseMap.returnGate;if(world==='camp'&&mission===S.GOBLINS){const alive=goblins.find(g=>!g.dead);return alive||camp.returnPortal}if(world==='city'){if(player.missionAI&&player.missionAI.active)return city.portal;if(mission===S.GO_GUILD||mission===S.RETURN_GUILD)return city.guildDoor;if(mission===S.PORTAL)return city.portal;if(mission===S.DONE&&currentCampaignMission())return orlaDeparture}if(world==='guild'){if(mission===S.REGISTER||mission===S.REPORT)return guild.reception;if(mission===S.CAPTAIN||mission===S.CAPTAIN_AFTER)return guild.captain;if(mission===S.BOARD)return guild.board;if(mission===S.PORTAL)return guild.exit}if(world==='orla'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_01')return orla.saira;if(cm==='mq_02')return orla.residents.find(r=>!(pr.rescued||[]).includes(r.id))||orla.saira;if(cm==='mq_03')return orla.clues.find(q=>!(pr.clues||[]).includes(q.id))||orla.ines;if(cm==='mq_04')return orla.cisternDoor;if(['mq_05','mq_06','mq_07','mq_08'].includes(cm))return roadDeparture;if(['mq_09','mq_10','mq_11','mq_12'].includes(cm))return quarryDeparture;if(['mq_13','mq_14','mq_15','mq_16','mq_17'].includes(cm))return gardenDeparture}if(world==='cistern'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_04'){const v=cistern.valves.find(v=>!(pr.valves||[]).includes(v.id));if(v)return v;return goblins.find(g=>!g.dead)||cistern.exit}}if(world==='road'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_05')return pr.metLio?road.firstGate:road.lio;if(cm==='mq_06'){const l=road.lanterns.find(x=>!(pr.lanterns||[]).includes(x.id));if(l)return l;return goblins.find(g=>!g.dead)||road.lio}if(cm==='mq_07')return road.manifests.find(m=>!(pr.manifests||[]).includes(m.id))||road.lio;if(cm==='mq_08')return goblins.find(g=>!g.dead)||road.finalGate}if(world==='quarry'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_09'){if(!pr.metAline)return quarry.aline;if(!pr.ledgerOpened)return quarry.ledger;return quarry.shiftCards.find(q=>!(pr.shiftCards||[]).includes(q.id))||quarry.aline}if(cm==='mq_10'){const b=quarry.brakes.find(x=>!(pr.brakes||[]).includes(x.id));if(b)return b;return goblins.find(g=>!g.dead)||quarry.aline}if(cm==='mq_11'){if(!pr.deep)return quarry.elevator;const w=quarry.workers.find(x=>!(pr.rescuedWorkers||[]).includes(x.id));return w||quarry.emergencyGate}if(cm==='mq_12')return goblins.find(g=>!g.dead)||quarry.bossPoint}if(world==='garden'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_13')return !pr.metNara?garden.nara:garden.samples.find(a=>!(pr.samples||[]).includes(a.id))||garden.nara;if(cm==='mq_14'){if(!pr.contractRead)return garden.contract;return garden.clauses.find(q=>!(pr.clauses||[]).includes(q.id))||garden.nara}if(cm==='mq_15'){const p=garden.plots.find(x=>!(pr.plots||[]).includes(x.id));if(p)return p;return goblins.find(g=>!g.dead)||garden.nara}if(cm==='mq_16'){const r=garden.commandRoots.find(x=>!(pr.commandRoots||[]).includes(x.id));if(r)return r;return goblins.find(g=>!g.dead)||garden.bossPoint}if(cm==='mq_17')return garden.returnGate}return null}
function arrowToTarget''','systems targets')

insert_draw=r'''function drawBaseDepartureMarker(){if(!player.guildRegistered)return;ctx.fillStyle='#59462f';ctx.fillRect(baseDeparture.x-50,baseDeparture.y-28,100,56);ctx.fillStyle='#9a7a4d';ctx.beginPath();ctx.moveTo(baseDeparture.x-58,baseDeparture.y-28);ctx.lineTo(baseDeparture.x,baseDeparture.y-70);ctx.lineTo(baseDeparture.x+58,baseDeparture.y-28);ctx.fill();label('SUA BASE',baseDeparture.x-32,baseDeparture.y-80,'#f0d6a5',13)}
function drawBase(){ensureMetaSystems();const b=player.base,bl=b.buildings;ctx.fillStyle='#283529';ctx.fillRect(0,0,baseMap.w,baseMap.h);ctx.fillStyle='#55442f';ctx.fillRect(170,150,1080,500);label('BASE PESSOAL',555,80,'#ead7ad',22);label('Retorno à cidade',45,670,'#ddd');const building=(o,name,lv,color)=>{ctx.fillStyle=color;ctx.fillRect(o.x-58,o.y-45,116,90);label(`${name} Nv.${lv}`,o.x-48,o.y-58,'#f0e1c0',13)};building(baseMap.shelter,'Abrigo',bl.shelter,'#70573f');building(baseMap.storage,'Depósito',bl.storage,'#665845');building(baseMap.farm,'Horta',bl.farm,'#4d7144');building(baseMap.workshop,'Oficina',bl.workshop,'#62544a');for(const n of baseMap.nodes){ctx.fillStyle=n.id==='wood'?'#55764a':n.id==='stone'?'#77766f':'#746653';ctx.beginPath();ctx.arc(n.x,n.y,30,0,Math.PI*2);ctx.fill();label(n.label,n.x-32,n.y-42,'#e7e0d2')}}
function drawRift(){ctx.fillStyle='#171b25';ctx.fillRect(0,0,rift.w,rift.h);for(let x=120;x<1450;x+=180){ctx.strokeStyle='#473d68';ctx.strokeRect(x,100+(x%240),110,70)}const a=player.missionAI&&player.missionAI.active;label(a?a.place:'Zona Instável',610,70,'#cdb8ff',22);for(const g of goblins){if(g.dead)continue;if(g.state==='windup'){ctx.fillStyle='#d33a';ctx.beginPath();ctx.arc(g.attackX,g.attackY,50,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#6d5d86';ctx.beginPath();ctx.arc(g.x,g.y,g.r,0,Math.PI*2);ctx.fill();label(g.name||'Alvo',g.x-38,g.y-g.r-12,'#ddd0ff');ctx.fillStyle='#222';ctx.fillRect(g.x-30,g.y+g.r+8,60,6);ctx.fillStyle='#b84b4b';ctx.fillRect(g.x-30,g.y+g.r+8,60*g.hp/g.maxHp,6)}if(a&&a.ready){portal(rift.returnPortal.x,rift.returnPortal.y);label('Concluir missão',rift.returnPortal.x-48,rift.returnPortal.y-55,'#ddd')}}
'''
s=s.replace('function drawCamp(){',insert_draw+'function drawCamp(){',1)
sub(r"function draw\(\)\{.*?\}\nfunction label",r'''function draw(){ctx.clearRect(0,0,W,H);if(!player)return;const map=mapForWorld();cam.x=Math.max(0,Math.min(map.w-W,player.x-W/2));cam.y=Math.max(0,Math.min(map.h-H,player.y-H/2));ctx.save();ctx.translate(-cam.x,-cam.y);if(world==='city'){drawCity();drawBaseDepartureMarker()}else if(world==='guild')drawGuild();else if(world==='orla'){drawOrla();drawRoadDepartureMarker();drawQuarryDepartureMarker();drawGardenDepartureMarker()}else if(world==='cistern')drawCistern();else if(world==='road')drawRoad();else if(world==='quarry')drawQuarry();else if(world==='garden')drawGarden();else if(world==='base')drawBase();else if(world==='rift')drawRift();else drawCamp();drawPlayer();ctx.restore();arrowToTarget();drawAim();updateHint()}
function label''','systems draw loop')

sub(r"function currentInteract\(\)\{.*?\}\nfunction updateHint",r'''function currentInteract(){if(!player)return'';if(world==='city'){if(near(city.guildDoor,82))return'Entrar na Guilda';if(player.guildRegistered&&near(baseDeparture,82))return'Entrar na sua Base';if(near({x:470,y:500},78))return'Davi Moura';if(near({x:1080,y:480},78))return'Breno Carvalho';if(near(city.portal,82)&&mission===S.PORTAL)return'Portal Rank F';if(near(city.portal,82)&&player.missionAI&&player.missionAI.active)return'Portal da missão dinâmica';const cs=readCampaignMain();if(cs&&cs.unlocked&&near(orlaDeparture,82))return'Viajar para Orla'}if(world==='guild'){if(near(guild.exit,82))return'Sair da Guilda';if(near(guild.reception,78))return'Elena Duarte';if(near(guild.captain,78))return'Raul Vilar';if(near({x:520,y:290},76))return'Caio Nunes';if(near({x:570,y:360},76))return'Mirela Santos';if(near(guild.board,78))return'Quadro de Missões'}if(world==='base'){if(near(baseMap.returnGate,82))return'Voltar à cidade';if(near(baseMap.shelter,76)||near(baseMap.storage,76)||near(baseMap.farm,76)||near(baseMap.workshop,76))return'Gerenciar Base';if(baseMap.nodes.some(n=>near(n,75)))return'Coletar recurso'}if(world==='rift'){if(player.missionAI&&player.missionAI.active&&player.missionAI.active.ready&&near(rift.returnPortal,86))return'Concluir missão'}if(world==='orla'){const cm=currentCampaignMission(),pr=progressMain();if(near(orla.returnGate,82))return'Voltar à Cidade Inicial';if(near(orla.saira,78))return'Saira Vento';if(near(orla.ines,78))return'Inês Lume';if(['mq_05','mq_06','mq_07','mq_08'].includes(cm)&&near(roadDeparture,88))return'Seguir pela Estrada das Lanternas';if(['mq_09','mq_10','mq_11','mq_12'].includes(cm)&&near(quarryDeparture,88))return'Viajar para as Pedreiras de Âmbar';if(['mq_13','mq_14','mq_15','mq_16','mq_17'].includes(cm)&&near(gardenDeparture,88))return'Viajar para o Jardim Suspenso';if(cm==='mq_02'&&orla.residents.some(r=>!(pr.rescued||[]).includes(r.id)&&near(r,75)))return'Resgatar morador';if(cm==='mq_03'&&orla.clues.some(q=>!(pr.clues||[]).includes(q.id)&&near(q,75)))return'Investigar evidência';if(cm==='mq_04'&&near(orla.cisternDoor,90))return'Entrar na Cisterna'}if(world==='road'){const cm=currentCampaignMission(),pr=progressMain();if(near(road.returnGate,82))return'Voltar para Orla';if(near(road.lio,78))return'Lio';if(cm==='mq_05'&&near(road.firstGate,78))return'Inspecionar a cancela';if(cm==='mq_06'&&road.lanterns.some(l=>!(pr.lanterns||[]).includes(l.id)&&near(l,75)))return'Reativar lanterna';if(cm==='mq_07'&&road.manifests.some(m=>!(pr.manifests||[]).includes(m.id)&&near(m,75)))return'Recolher manifesto'}if(world==='quarry'){const cm=currentCampaignMission(),pr=progressMain();if(near(quarry.returnGate,82))return'Voltar para Orla';if(near(quarry.aline,78))return'Aline Moura';if(cm==='mq_09'&&near(quarry.ledger,75))return'Conferir Livro de Pagamento';if(cm==='mq_10'&&quarry.brakes.some(b=>!(pr.brakes||[]).includes(b.id)&&near(b,75)))return'Acionar freio de emergência';if(cm==='mq_11'&&!pr.deep&&near(quarry.elevator,82))return'Descer pelo elevador'}if(world==='garden'){const cm=currentCampaignMission(),pr=progressMain();if(near(garden.returnGate,82))return'Voltar para Orla';if(near(garden.nara,78))return'Nara Reis';if(cm==='mq_13'&&garden.samples.some(a=>!(pr.samples||[]).includes(a.id)&&near(a,75)))return'Coletar amostra';if(cm==='mq_14'&&near(garden.contract,75))return'Ler contrato original';if(cm==='mq_15'&&garden.plots.some(p=>!(pr.plots||[]).includes(p.id)&&near(p,78)))return'Proteger lote';if(cm==='mq_16'&&garden.commandRoots.some(r=>!(pr.commandRoots||[]).includes(r.id)&&near(r,78)))return'Separar raiz de comando'}if(world==='camp'&&goblins.filter(g=>g.dead).length>=5&&near(camp.returnPortal,82))return'Portal de retorno';return''}
function updateHint''','systems hints')

