new_key="addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.code==='KeyQ')useSkill('q');else if(e.code==='KeyE'&&(!currentInteract()||e.shiftKey))useSkill('e');else if(e.code==='KeyR')useSkill('r');else if(e.key.toLowerCase()==='e')interact()});"
rep(old_key,new_key,'skill keys')
s=s.replace("else if(e.code==='KeyE'&&(!currentInteract()||e.shiftKey))useSkill('e');else if(e.code==='KeyR')useSkill('r');else if(e.key.toLowerCase()==='e')interact()","else if(e.code==='KeyE'){if(currentInteract()&&!e.shiftKey)interact();else useSkill('e')}else if(e.code==='KeyR')useSkill('r')",1)

